#!/usr/bin/env node/** * BANF Comprehensive Test Agent v3.0 * ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ * Full-coverage automated test suite for the BANF Wix platform. * Tests every implemented API endpoint, all workflows, data integrity, * performance SLAs, and security requirements. * * Results: PASS / FAIL / SKIP *   PASS  ΓÇö endpoint works and meets expectations *   FAIL  ΓÇö endpoint works but returns wrong data *   SKIP  ΓÇö endpoint not yet implemented OR requires Wix member session * * Usage:  node banf-comprehensive-test-agent.js [--verbose] [--quick] * ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ */'use strict';const fs   = require('fs');const path = require('path');// ΓöÇΓöÇΓöÇ Config ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇconst BASE       = 'https://banfwix.wixsite.com/banf1/_functions';const SITE_URL   = 'https://banfwix.wixsite.com/banf1';const ADMIN_KEY  = 'IST.eyJraWQiOiJQb3pIX2FDMiIsImFsZyI6IlJTMjU2In0..GVx8jeX6lw2qF3cTWQJX4hWVs_unIkBJAgywR_sbASHyJhs95w6euuWIRW5CfQ_PSZmCKHw6ma5IpQawGhR79hYUi46_49yAg9fCklP60iJJlPLKdLj6NtOVIoYoc-WsG8nOW_9qo1om08YA-Qh_5O-oZv6oRW2gk7C2eOF5E1pjt0CgmVIRK8z5HvVqlXYftO9NtaSfHh9vhSVPkxVU6jp1OJBsR_UdcdL6Rpiv-bJx0hKJJOfNJMc89oEBiCaAJ4No65-FsGouo2yIYUCsDAQTtBk9rWh3cH8_n-ts0WK57kdtXVKRqQ5g7ch5usUdFAUBTSaviGXpExj5VoTVKQ';const ADMIN_EMAIL = 'banfjax@gmail.com';const HDRS = { 'Content-Type': 'application/json', 'x-user-email': ADMIN_EMAIL };const VERBOSE = process.argv.includes('--verbose');const QUICK   = process.argv.includes('--quick');// ΓöÇΓöÇΓöÇ Test Harness ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇconst results = [];let passed = 0, failed = 0, skipped = 0;function esc(s) { return (s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }function logLine(status, group, name, details, latency) {  const ic = { PASS: 'Γ£à', FAIL: 'Γ¥î', SKIP: 'ΓÅ¡∩╕Å ' };  const lat = latency ? ` (${latency}ms)` : '';  console.log(`  ${ic[status] || '  '} [${group}] ${name}${lat}`);  if (details && (status !== 'PASS' || VERBOSE)) console.log(`       ΓåÆ ${details}`);}function record(group, name, status, details = '', latency = null, response = null) {  const r = {    group, name, status, details, latency,    timestamp: new Date().toISOString(),    response: response ? JSON.stringify(response).substring(0, 500) : null,  };  results.push(r);  if (status === 'PASS')  passed++;  else if (status === 'FAIL') failed++;  else skipped++;  logLine(status, group, name, details, latency);  return r;}function pass(g, n, d = '', l = null, resp = null) { return record(g, n, 'PASS', d, l, resp); }function fail(g, n, d = '', l = null, resp = null) { return record(g, n, 'FAIL', d, l, resp); }function skip(g, n, d = '')                        { return record(g, n, 'SKIP', d); }// ΓöÇΓöÇΓöÇ HTTP Helpers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇasync function apiGet(ep, params = {}, timeout = 15000) {  const sep = ep.includes('?') ? '&' : '?';  const qs  = new URLSearchParams({ ...params, admin_key: ADMIN_KEY }).toString();  const url = `${BASE}/${ep}${sep}${qs}`;  const t0  = Date.now();  try {    const r = await fetch(url, { headers: HDRS, signal: AbortSignal.timeout(timeout) });    const text = await r.text();    let json;    try { json = JSON.parse(text); } catch { json = { _raw: text.substring(0, 200) }; }    return { ok: r.ok, status: r.status, json, latency: Date.now() - t0 };  } catch (e) {    return { ok: false, status: 0, json: null, error: e.message, latency: Date.now() - t0 };  }}async function apiPost(ep, body = {}, timeout = 15000) {  const url = `${BASE}/${ep}?admin_key=${ADMIN_KEY}`;  const t0  = Date.now();  try {    const r = await fetch(url, {      method: 'POST', headers: HDRS,      body: JSON.stringify(body),      signal: AbortSignal.timeout(timeout),    });    const text = await r.text();    let json;    try { json = JSON.parse(text); } catch { json = { _raw: text.substring(0, 200) }; }    return { ok: r.ok, status: r.status, json, latency: Date.now() - t0 };  } catch (e) {    return { ok: false, status: 0, json: null, error: e.message, latency: Date.now() - t0 };  }}async function httpGet(url, timeout = 10000) {  const t0 = Date.now();  try {    const r = await fetch(url, { signal: AbortSignal.timeout(timeout) });    const text = await r.text();    return { ok: r.ok, status: r.status, text, headers: Object.fromEntries(r.headers.entries()), latency: Date.now() - t0 };  } catch (e) {    return { ok: false, status: 0, text: '', error: e.message, latency: Date.now() - t0 };  }}// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ// SHARED STATE  (populated by early tests, used by later ones)// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇconst state = {};// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ//  1. INFRASTRUCTURE & HEALTH// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉasync function testInfrastructure() {  console.log('\nΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ');  console.log('  1. INFRASTRUCTURE & HEALTH');  console.log('ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ');  // 1a. Site HTTP 200  const site = await httpGet(SITE_URL);  record('infrastructure', 'Live site returns HTTP 200',    site.status === 200 ? 'PASS' : 'FAIL',    `Status: ${site.status}`, site.latency);  // 1b. Functions base reachable  const health = await apiGet('health');  record('infrastructure', 'Health endpoint returns 200',    health.ok ? 'PASS' : 'FAIL',    `Status: ${health.status}`, health.latency);  // 1c. Health response has version/status fields  record('infrastructure', 'Health response has status field',    health.json?.status === 'healthy' ? 'PASS' : 'FAIL',    `status: ${health.json?.status}`, null, health.json);  // 1d. Health response has timestamp  record('infrastructure', 'Health response has timestamp',    !!health.json?.timestamp ? 'PASS' : 'FAIL',    `timestamp: ${health.json?.timestamp}`);  // 1e. API version in health response  record('infrastructure', 'Health response has API version',    !!(health.json?.version || health.json?.apiVersion) ? 'PASS' : 'FAIL',    `version: ${health.json?.version || health.json?.apiVersion || 'missing'}`);  // 1f. CORS ΓÇö OPTIONS on health returns CORS header  const corsUrl = `${BASE}/health?admin_key=${ADMIN_KEY}`;  const cors = await fetch(corsUrl, { method: 'OPTIONS', signal: AbortSignal.timeout(8000) }).catch(() => null);  const corsHeader = cors ? cors.headers.get('access-control-allow-origin') || cors.headers.get('Access-Control-Allow-Origin') : null;  record('infrastructure', 'CORS OPTIONS returns allow-origin header',    corsHeader !== null ? 'PASS' : 'SKIP',    corsHeader ? `Origin: ${corsHeader}` : 'CORS header not present (Wix may handle via CDN)');}// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ//  2. CRM MEMBER MANAGEMENT// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉasync function testCRMMembers() {  console.log('\nΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ');  console.log('  2. CRM MEMBER MANAGEMENT');  console.log('ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ');  // 2a. crm_members list  const list = await apiGet('crm_members', { limit: 200 });  record('crm_members', 'GET crm_members ΓÇö returns member list',    list.ok ? 'PASS' : 'FAIL',    `Status: ${list.status}, members: ${list.json?.members?.length ?? 'N/A'}`, list.latency, list.json?.members?.[0]);  const mems = list.json?.members || [];  state.members = mems;  // 2b. Count >= 100  record('crm_members', 'CRM has ΓëÑ 100 members',    mems.length >= 100 ? 'PASS' : 'FAIL',    `Count: ${mems.length}`);  // 2c. crm_member by ID  const withId = mems.find(m => m.memberId);  if (withId) {    state.memberId   = withId.memberId;    state.memberDbId = withId._id;    const single = await apiGet('crm_member', { memberId: withId.memberId });    record('crm_members', 'GET crm_member ΓÇö returns single member by ID',      single.ok && single.json?.member ? 'PASS' : 'FAIL',      `Status: ${single.status}, member: ${single.json?.member?.displayName}`,      single.latency, single.json?.member);    state.memberName = withId.displayName;  } else {    skip('crm_members', 'GET crm_member by ID', 'No member with memberId found in list');  }  // 2d. crm_member_search with known name  const searchName = (state.memberName || 'Mita').split(' ')[0];  const search = await apiGet('crm_member_search', { q: searchName, limit: 10 });  record('crm_members', `GET crm_member_search ΓÇö finds "${searchName}"`,    search.ok && (search.json?.members?.length ?? 0) > 0 ? 'PASS' : 'FAIL',    `Status: ${search.status}, results: ${search.json?.members?.length ?? 0}`,    search.latency, search.json?.members?.[0]);  // 2e. Members have required fields (allow Γëñ 2 bad records from imports)  const missingFields = mems.filter(m => !m._id);  record('crm_members', 'All members have required CRM fields (_id)',    missingFields.length === 0 ? 'PASS' : 'FAIL',    missingFields.length === 0 ? 'All members have _id' : `${missingFields.length} members missing _id`);  // 2e2. displayName coverage (non-empty) ΓÇö allow Γëñ 1% blank due to import artifacts  const blankName = mems.filter(m => !m.displayName);  record('crm_members', 'Member displayName coverage ΓëÑ 99% (import quality)',    blankName.length <= Math.max(2, mems.length * 0.01) ? 'PASS' : 'FAIL',    `${mems.length - blankName.length}/${mems.length} have displayName (${blankName.length} blank)`);  // 2e3. Audit membershipType coverage  const missingMtype = mems.filter(m => !m.membershipType);  record('crm_members', 'membershipType coverage ΓëÑ 25% (audit)',    missingMtype.length <= mems.length * 0.75 ? 'PASS' : 'FAIL',    `${mems.length - missingMtype.length}/${mems.length} members have membership