 console.log(`  Pass Rate (excl. SKIP): ${passRate}%`);  console.log(`  Duration: ${duration}s`);  // Show any failures  const failures = results.filter(r => r.status === 'FAIL');  if (failures.length > 0) {    console.log('\n  Γ¥î FAILURES:');    failures.forEach(r => console.log(`     [${r.group}] ${r.name}\n       ΓåÆ ${r.details}`));  }  // Save HTML report  const html = generateHTMLReport(startTime, endTime);  const htmlPath = path.join(__dirname, 'banf-comprehensive-report.html');  fs.writeFileSync(htmlPath, html);  console.log(`\n  ≡ƒôä HTML Report: ${htmlPath}`);  // Save JSON  const jsonPath = path.join(__dirname, 'banf-comprehensive-results.json');  fs.writeFileSync(jsonPath, JSON.stringify({    version: 'v3.0',    site: SITE_URL,    generatedAt: new Date().toISOString(),    duration,    summary: { total, passed, failed, skipped, passRate },    results,  }, null, 2));  console.log(`  ≡ƒôè JSON Results: ${jsonPath}`);  console.log('\nΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ\n');  process.exit(failed > 0 ? 1 : 0);}main().catch(e => { console.error('FATAL:', e); process.exit(1); });